/**
 * Badge. A small molded/LCD status label. Composes
 * var(--echo-*) only; white/black alphas are the single-key-light model.
 */
.echo-badge {
  /*
   * An inline-layout root grows to fit its content, so a long label
   * pushed the container open rather than the component adapting. Capping it
   * at the container is what lets the truncation and wrapping below take
   * effect at all.
   */
  max-width: 100%;
  /* The cap counts the padding too (BUG-128). */
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  gap: var(--echo-space-3);
  padding: var(--echo-space-2) var(--echo-space-5);
  border-radius: var(--echo-radius-full);
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-2xs);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-wide, 0.06em);
  line-height: var(--echo-leading-snug, 1.4);
  text-transform: uppercase;
  /* Stays on one line, so long content truncates. */
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.echo-badge[data-size="sm"] {
  padding: var(--echo-space-1) var(--echo-space-4);
  font-size: var(--echo-text-3xs);
}

.echo-badge[data-variant="neutral"] {
  color: var(--echo-text);
  background: linear-gradient(180deg, var(--echo-cap-highlight) 0%, var(--echo-cap) 100%);
  box-shadow: var(
    --echo-shadow-chip,
    inset 0 1px 0 rgb(255 255 255 / calc(0.15 * var(--echo-gloss, 1))),
    0 1px 2px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.4 * var(--echo-shade, 1) * 100%), transparent)
  );
}

/* The primary cap, like every lit control — not a second, lighter accent. */
.echo-badge[data-variant="accent"] {
  color: var(--echo-primary-cap-ink, var(--echo-text));
  background: linear-gradient(
    180deg,
    var(--echo-primary-cap-top) 0%,
    var(--echo-primary-cap-mid) 45%,
    var(--echo-primary-cap-base) 100%
  );
  /* A lit top edge, no halo — the library throws no outer glows. */
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / calc(0.35 * var(--echo-gloss, 1))),
    inset 0 -1px 0 color-mix(in oklab, var(--echo-cast-ink, black) calc(0.25 * var(--echo-shade, 1) * 100%), transparent);
}

.echo-badge[data-variant="lcd"] {
  color: var(--echo-accent-ink, var(--echo-accent-glow));
  background: var(--echo-lcd);
  box-shadow:
    inset 0 1px 3px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.8 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1)));
  text-shadow: 0 0 6px color-mix(in oklab, var(--echo-lcd-glow) 60%, transparent);
}

.echo-badge[data-variant="outline"] {
  color: var(--echo-text-dim);
  background: transparent;
  box-shadow: inset 0 0 0 1px var(--echo-seam);
}

/**
 * Badge — a small molded/LCD status label.
 * Static; consumes only var(--echo-*) via badge.css.
 */
import type { HTMLAttributes } from "react";
import "./badge.css";

export type BadgeVariant = "neutral" | "accent" | "lcd" | "outline";
export type BadgeSize = "sm" | "md";

export interface BadgeProps extends HTMLAttributes<HTMLSpanElement> {
  variant?: BadgeVariant;
  size?: BadgeSize;
}

export function Badge({ variant = "neutral", size = "md", className, children, ...rest }: BadgeProps) {
  return (
    <span
      className={["echo-badge", className].filter(Boolean).join(" ")}
      data-variant={variant}
      data-size={size}
      {...rest}
    >
      {children}
    </span>
  );
}
